/**
 * Nodes of the forest map (design: docs/roguelike-runs.md): types, lanes, content and the base numbers of the run.
 * Pure data; the map itself is generated by the run seed (mapGenerator.ts).
 *
 * Moved from the removed turn-based game (src/game/run/forestMap.ts, tag `turn-based-final`). The authored graph and the
 * trunk (map rows 1–4, the turn-based tutorial) stayed there: a real-time run always started past them, at map row 5, and
 * the map rows keep their numbers (node ids carry them, `r5c0`, and the node seed is derived from the id).
 */
import type { AbilityKind, ItemKind } from './types';

/** `hard` — the hard battle; `checkpoint` — the Jailer's row (row 9), where every path meets. */
export type ForestNodeType = 'battle' | 'hard' | 'rest' | 'find' | 'event' | 'shop' | 'breakthrough' | 'boss' | 'checkpoint';
/** First-half trails (beasts/goblins/shared) and second-half branches (den, camp). */
export type ForestLane = 'beasts' | 'goblins' | 'shared' | 'den' | 'camp';

export type ForestNodeContent =
  | { kind: 'rest'; heal: number }
  | { kind: 'find' }
  /** The merchant (docs/roguelike-runs.md, 5б; merchant.ts): goods for crafting resources. */
  | { kind: 'shop' }
  /** A node whose arena or event is taken from its pool on entering (src/realtime/run/arenaPools.ts, rtRun.ts). */
  | { kind: 'pool' };

/** Tools a node's row opens (kept on the generated nodes as the turn-based map gave them; the real-time run opens all at the start). */
export interface ForestNodeGrant { items?: ItemKind[]; abilities?: AbilityKind[]; inventory?: Partial<Record<ItemKind, number>> }

export interface ForestMapNode {
  id: string;
  type: ForestNodeType;
  name: string;
  lane: ForestLane;
  /** Map row: 5 is the first row of a run (rows 1–4 were the turn-based trunk); column 0 left, 1 centre, 2 right. */
  row: number;
  column: 0 | 1 | 2;
  /** Vertical place on the map screen, 0 (top) – 1 (bottom). */
  slot?: number;
  content: ForestNodeContent;
  next: string[];
  grants?: ForestNodeGrant;
  /** Granted after a won battle. */
  rewardGrants?: ForestNodeGrant;
}

/** Rest heal, HP up to the maximum, in turn-based HP (×RT_HP_SCALE in the real-time run, hpScale.ts). */
export const FOREST_REST_HEAL = 2;
/** Hard-battle victory heal, in turn-based HP (×RT_HP_SCALE), given together with the talisman choice. */
export const FOREST_HARD_HEAL = 1;
/** HP of a turn-based run: the unit of every HP number of this layer (the real-time run scales it, hpScale.ts). */
export const FOREST_RUN_START_HP = 5;
/** The last map row of the removed turn-based trunk: a real-time run starts at the next row (run row = map row − this). */
export const FOREST_TRUNK_LAST_ROW = 4;

/** Grants of the first trail row (frost, one flask) and of the jump row; the generated map gives them by row. */
export const FROST: ForestNodeGrant = { items: ['frost'], inventory: { frost: 1 } };
export const JUMP: ForestNodeGrant = { abilities: ['jump'] };
/** Reward of the checkpoint victory: the spin. */
export const SPIN_REWARD: ForestNodeGrant = { abilities: ['spin'] };

/** The graph a run walks: the generated map (mapGenerator.ts). `starts()`: the first transitions of a run (map row 5). */
export interface ForestRunMap {
  kind: 'generated';
  nodes: readonly ForestMapNode[];
  node(id: string): ForestMapNode | undefined;
  starts(): string[];
}

/**
 * The choice that follows a victory before the next transition (docs/talismans.md, decision of 04.10.2026): a hard
 * battle offers talismans, the Jailer checkpoint offers oaths; null — none.
 */
export function victoryChoice(node: ForestMapNode): 'hard' | 'oath' | null {
  return node.type === 'hard' ? 'hard' : node.type === 'checkpoint' ? 'oath' : null;
}
